// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract Reverter {
    fallback() external payable { revert(); }
    receive() external payable { revert(); }
}

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function testFuzz_property(uint256 amount, uint256 extra) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, type(uint128).max);
        extra = bound(extra, 0, type(uint128).max);

        Reverter reverter = new Reverter();
        address actor = address(reverter);

        vm.deal(actor, amount);

        // Fund the caller through the public payable surface.
        vm.prank(actor);
        c.addToBalance{value: amount}();

        // Give c extra Ether so payment is not limited by c's balance.
        if (extra > 0) {
            vm.deal(address(c), address(c).balance + extra);
        }

        uint256 before = c.getBalance(actor);

        // The external call to `actor` reverts; reference reverts and rolls back,
        // mutant swallows the failed send and keeps the zeroing.
        vm.prank(actor);
        try c.withdrawBalance() {} catch {}

        uint256 afterBal = c.getBalance(actor);

        assertTrue(
            afterBal == before,
            "failed withdrawal must not permanently change stored balance"
        );
    }
}
